def choose_move(observation):
    px, py = observation['self_position']
    opp_x, opp_y = observation['opponent_position']
    width, height = observation['grid_width'], observation['grid_height']
    obstacles = set(observation.get('obstacles', []))
    resources = observation.get('resources', [])
    remaining = observation.get('remaining_resource_count', 0)

    def safe_move(dx, dy):
        nx, ny = px + dx, py + dy
        return 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles

    for dx, dy in [(0,-1),(0,1),(-1,0),(1,0)]:
        if safe_move(dx, dy):
            break
    else:
        dx, dy = 0,0

    dist_list = []
    for rx, ry in resources:
        d = abs(rx - px) + abs(ry - py)
        dist_list.append(((rx, ry), d))
    if dist_list:
        target, _ = min(dist_list, key=lambda t: t[1])
        tx, ty = target
        if px < tx and safe_move(1,0):
            return [1,0]
        if px > tx and safe_move(-1,0):
            return [-1,0]
        if py < ty and safe_move(0,1):
            return [0,1]
        if py > ty and safe_move(0,-1):
            return [0,-1]

    return [dx, dy]
